INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 0, 321, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 40011, 1, 24001, 125801, 1, 2, "リリ");
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 0, 322, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 40011, 1, 24001, 126001, 2, 2, "クリア");
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 0, 323, "んーと。\nこれ、あげる。\nはい", 40011, 1, 24001, 126101, 3, 2, "プレシア");
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 0, 324, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 40011, 2, 24001, 125801, 4, 2, "リリ");
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 0, 325, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 40011, 2, 24001, 126001, 5, 2, "クリア");
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 0, 326, "お兄。\nきてくれて、うれしい", 40011, 2, 24001, 126101, 6, 2, "プレシア");
